// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address to, uint256 v) public {
        // Bound v to avoid overflow issues, keep wide
        v = uint256(bound(v, 1, type(uint128).max));

        // Make 'from' and 'to' different to avoid zero-address or same-address edge cases
        vm.assume(from != address(0) && to != address(0) && from != to);
        vm.assume(from != address(c) && to != address(c));

        // Deploy an adversarial callee that implements transferFrom but not transfer
        // The reference uses transferFrom -> succeeds; the mutant uses transfer -> fails
        TransferFromCallee callee = new TransferFromCallee();

        // Build a _tos array with the single address 'to'
        address[] memory tos = new address[](1);
        tos[0] = to;

        bool refOk;
        bool mutOk;

        // Call reference-style transfer (selector transferFrom)
        try c.transfer(from, address(callee), tos, v) {
            refOk = true;
        } catch {
            refOk = false;
        }

        // For the mutant behavior we simulate the buggy code by checking what the mutant's selector would do.
        // The mutant uses transfer(address,uint256) which our callee does NOT implement, so the low-level call returns false.
        // We can't call the mutant directly, but we can observe that the reference succeeds and the expected mutant behavior fails.
        // To do this, we construct the exact call the mutant makes and check its success directly:
        bytes4 mutantSelector = bytes4(keccak256("transfer(address,uint256)"));
        (bool mutantCallSuccess, ) = address(callee).call(abi.encodeWithSelector(mutantSelector, to, v));
        mutOk = mutantCallSuccess;

        // Assert: reference succeeds AND mutant would fail on the same callee that implements transferFrom but not transfer
        // The property: The external call through C's transfer using transferFrom always succeeds on this callee,
        // whereas the mutant's external call using transfer fails.
        assertTrue(refOk && !mutOk);
    }
}

// Adversarial callee that implements transferFrom but NOT transfer
contract TransferFromCallee {
    // fallback: fails for any unknown selector (including 'transfer(address,uint256)')
    fallback() external payable {
        revert("unknown selector");
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        // succeed without side effects
        return true;
    }
}

