pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(0));
        TokenMock token = new TokenMock();
        for(uint i=0; i<_tos.length; i++){
            token.setBalance(_tos[i], 0);
        }
        token.setBalance(from, v * _tos.length + 1);
        vm.prank(from);
        c.transfer(from, address(token), _tos, v);
        uint sum;
        for(uint i=0; i<_tos.length; i++){
            sum += token.balanceOf(_tos[i]);
        }
        assertTrue(sum == 0 || sum == v * _tos.length);
    }
}

contract TokenMock {
    mapping(address => uint) public balanceOf;
    function transferFrom(address from, address to, uint amount) external returns (bool) {
        require(balanceOf[from] >= amount, "insufficient");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
    function setBalance(address who, uint bal) external {
        balanceOf[who] = bal;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(caddress != address(0));
        vm.assume(_tos.length > 0);
        vm.assume(v > 0);
        // deploy a helper that records the last call argument
        CallRecorder recorder = new CallRecorder();
        // use the recorder's address as caddress
        vm.prank(from);
        bool ok = c.transfer(from, address(recorder), _tos, v);
        assertTrue(ok);
        // check that every call received v
        for (uint i = 0; i < _tos.length; i++) {
            assertEq(recorder.lastAmount(i), v);
        }
    }
}

contract CallRecorder {
    uint256[] public lastAmount;
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastAmount.push(amount);
        return true;
    }
}
